package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a yyyy-mm period for each month first..last, leaving out a month whose name is already a period on the
 *  sheet (without regard to case) or whose days overlap a period on the sheet. */
public class SaveGeneratedPeriods {
    public void save(@PathVariable("sheetId") String sheetId, @Val PeriodGenerateInput input,
            PeriodRepository repository, Out<GeneratedPeriods> generated) {
        String id = sheetId.trim();
        repository.lockSheet(id);
        List<Period> existing = new ArrayList<>(repository.list(id));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = input.first(); !month.isAfter(input.last()); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate from = month.atDay(1);
            LocalDate to = month.atEndOfMonth();
            boolean taken = existing.stream()
                    .anyMatch(p -> p.name().trim().equalsIgnoreCase(name) || p.overlaps(from, to));
            if (taken) {
                continue;
            }
            Period period = repository.insert(id, name, from, to);
            existing.add(period);
            made.add(period);
        }
        generated.set(new GeneratedPeriods(made));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record each generated period in the audit file as an add, in month order. */
public class AuditPeriodsGenerated {
    public void audit(@Val PeriodGenerateInput input, @Val GeneratedPeriods generated, Audit audit) {
        for (Period period : generated.periods()) {
            audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + input.user()
                    + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse a period whose name another period on the sheet already has (without regard to case), or whose
 *  dates overlap another period's. */
public class ValidateNewPeriod {
    public void validate(@PathVariable("sheetId") String sheetId, @Val PeriodInput input,
            PeriodRepository repository) throws InvalidPeriodException {
        String id = sheetId.trim();
        repository.lockSheet(id);
        for (Period p : repository.list(id)) {
            if (p.name().trim().equalsIgnoreCase(input.name())) {
                throw new InvalidPeriodException("The period name " + input.name() + " is already in use on this sheet.");
            }
            if (p.overlaps(input.from(), input.to())) {
                throw new InvalidPeriodException("The dates overlap the period " + p.name() + ".");
            }
        }
    }
}

